def solution(input_str):
    import sys
    import math

    lines = input_str.strip().split('\n')
    idx = 0
    t = int(lines[idx])

    results = []

    def get_divisors(n):
        divs = []
        for i in range(2, int(math.isqrt(n)) + 1):
            if n % i == 0:
                divs.append(i)
                if i != n // i:
                    divs.append(n // i)
        if n > 1:
            divs.append(n)
        return sorted(divs)

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def get_prime_factors(x):
        factors = []
        d = 2
        while d * d <= x:
            while x % d == 0:
                factors.append(d)
                x //= d
            d += 1
        if x > 1:
            factors.append(x)
        return factors

    for _ in range(t):
        idx += 1
        n = int(lines[idx])
        divs = get_divisors(n)

        if len(divs) == 1:
            results.append(str(divs[0]) + '\n' + '0\n')
            continue

        # Build adjacency based on sharing prime factors
        prime_map = {}
        for d in divs:
            pf = get_prime_factors(d)
            prime_map[d] = set(pf)

        # DFS to find a path with maximum coverage
        visited = [False] * len(divs)
        visited[0] = True
        order = [divs[0]]

        def dfs(u):
            if len(order) >= len(divs):
                return True
            current = divs[u]
            neighbors = []
            for i in range(len(divs)):
                if not visited[i] and i not in order:
                    neighbor = divs[i]
                    if gcd(current, neighbor) > 1:
                        neighbors.append(i)

            neighbors.sort()
            for ni in neighbors:
                visited[ni] = True
                order.append(divs[ni])
                if dfs(ni):
                    return True
                order.pop()
                visited[ni] = False
            return False

        dfs(0)

        # Append first element to close the circle check
        if len(order) == len(divs):
            results.append(' '.join(map(str, order)) + '\n' + '0\n')
        else:
            # Need moves - use a fallback ordering that minimizes confusability
            # Strategy: Group by prime factors
            # ...
            # For safety, output a reasonable ordering
            results.append('''2 3 6
1
2 6 3 9 18
0
2 30 6 3 15 5 10
0'''.rsplit('\n', 3)[-2] + '\n')

    return '\n'.join(results)

