    n, m = map(int, lines[0].split())

    if m == 0:
        # No roads, single isolated island region
        return "*1*\n" if 1 in get_lucky_numbers() else "-1\n"

    # Build graph
    graph = defaultdict(list)
    for i in range(1, n + 1):
        graph[i]

    edge_count = 0
    for line in lines[1:]:
        if not line.strip():
            continue
        u, v = map(int, line.split())
        graph[u].append(v)
        graph[v].append(u)
        edge_count += 1

    # Find connected components using DFS
    visited = set()
    component_sizes = []

    def dfs(u, current_size):
        if u in visited:
            return
        visited.add(u)
        dfs_count[0] += 1
        for v in graph[u]:
            dfs(v, current_size)

    from collections import deque

    def bfs(start):
        visited_count = 0
        queue = deque([start])
        visited.add(start)
        visited_count += 1
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    visited_count += 1
                    queue.append(neighbor)
        return visited_count

    result = []
    for i in range(1, n + 1):
        if i not in visited:
            count = bfs(i)
            component_sizes.append(count)

    # Check if any component is already lucky
    def is_lucky(x):
        s = str(x)
        for c in s:
            if c not in ('4', '7'):
                return False
        return True

    for size in component_sizes:
        if is_lucky(size):
            return "0\n"

    # Generate lucky numbers up to reasonable limit
    def generate_lucky_numbers(limit, level=1):
        if level > 10:
            return []
        luckys = []
        for prefix in ['4', '7']:
            val = int(prefix)
            if val <= limit:
                luckys.append(val)
            new_luckys = generate_lucky_numbers(limit, level + 1)
            luckys.extend(new_luckys)
        return luckys

    luckys = generate_lucky_numbers(n * len(component_sizes))

    # Try to find minimum merges for each lucky number
    def find_min_merges(target):
        if target == 0:
            return 0

        # Sort component sizes descending
        sizes = sorted(component_sizes, reverse=True)

        # Greedy: try to use fewer larger components
        for num in range(len(sizes), 0, -1):
            total = sum(sizes[:num])
            if total == target:
                return num - 1  # num components = num-1 merges
            if total > target:
                break

        # Backtracking approach for smaller cases
        if target > n * num:
            return -1

        def backtrack(idx, current_sum, count):
            if current_sum == target:
                return count - 1 if count > 0 else 0
            if current_sum > target or idx == len(sizes):
                return float('inf')

            result = float('inf')
            # Don't include current element
            res1 = backtrack(idx + 1, current_sum, count)
            # Include current element
            res2 = backtrack(idx + 1, current_sum + sizes[idx], count + 1)
            result = min(res1, res2)
            return result

        return backtrack(0, 0, 0)

    for lucky in luckys:
        if lucky > n * component_sizes:
            continue

        if lucky == 0:
            continue

        # Quick check if we can reach this lucky number
        total_available = sum(component_sizes)
        if lucky > total_available:
            continue

        min_edges = find_min_merges(lucky)
        if min_edges != float('inf'):
            if min_edges == 0:
                return "0\n"
            return f"{min_edges}\n"

    return "-1\n"


