    n, k = map(int, lines[0].split())
    s = lines[1]

    # Convert string to list with positions for analysis
    def get_n_possibilities(arr, allN=False, allY=False):
        """Get max consecutive N with given assignments for ?"""
        consecutive = 0
        result = 0
        for c in arr:
            if c == 'N':
                consecutive += 1
            elif c == 'Y':
                result = max(result, consecutive)
                consecutive = 0
            else:  # '?'
                if allN:
                    consecutive += 1
                elif allY:
                    pass
                else:
                    consecutive += 1 if allN else 0
        result = max(result, consecutive)
        return result

    # Check 1: With all '?' treated as 'Y', max consecutive N should be <= k
    temp_s = list(s)
    for i in range(n):
        if temp_s[i] == '?':
            temp_s[i] = 'Y'
    max_N_with_allY = 0
    consecutive = 0
    for c in temp_s:
        if c == 'N':
            consecutive += 1
        else:
            max_N_with_allY = max(max_N_with_allY, consecutive)
            consecutive = 0
    max_N_with_allY = max(max_N_with_allY, consecutive)

    if max_N_with_allY > k:
        return "NO"

    # Check 2: With some '?' treated as 'N', can we make at least one run of exactly k?
    # This is possible if:
    # - Either there's already a run of exactly k with minimal treatment
    # - Or we can create one by setting some '?' to 'N'

    # Find existing N positions
    n_positions = [i for i in range(n) if s[i] == 'N']

    # Check if we can form a run of k consecutive N's
    # We can do this if:
    # 1. There's an existing N position or ? position to start a k-length run
    # 2. All positions in the run can become N (fixed N or ?)
    # 3. The run + its extensions don't exceed k (need to check nearby positions)

    def can_make_k(p):
        """Check if we can make exactly k consecutive N's starting at position p"""
        if p + k > n or p < 0:
            return False

        # Check if all positions from p to p+k-1 can become N
        for i in range(p, p+k):
            if s[i] == 'Y':
                return False

        # After creating this run, check if maximum stays <= k
        # For this, we assume '?' become N only in this run, and Y elsewhere
        arr = list(s)
        for i in range(n):
            if i >= p and i < p+k:
                arr[i] = 'N'
            elif s[i] == '?':
                arr[i] = 'Y'  # all other ? become Y

        # Calculate max consecutive N's with this specific assignment
        temp_arr = arr[:]
        consecutive = 0
        result = 0
        for c in temp_arr:
            if c == 'N':
                consecutive += 1
            else:
                result = max(result, consecutive)
                consecutive = 0
        result = max(result, consecutive)

        return result == k

    # Check if there exists any position where we can make k consecutive N's
    for p in range(n):
        if can_make_k(p):
            return "YES"

    # Special check for k=0 case
    if k == 0:
        # For k=0, we need NO consecutive N's at all
        # All ? must become Y, and all existing N positions must not create runs
        # But if any fixed N exists, and no run exceeds 0, that means no consecutive N
        # Actually k=0 means maximum consecutive N = 0, so individual N's are OK, 
        # but we need to check the arrangement

        # If k=0 and we have N's, we need to ensure no two N's are adjacent
        # Actually, if the max consecutive N's = 0, that's impossible since a single N is consecutive count 1
        # So k=0 is only possible if there are NO N's (after setting ? to Y)

        for i in range(n):
            if s[i] == 'N':
                if i > 0 and s[i-1] == 'N':
                    return "NO"

        # Any N at all means min consecutive is 1, so k must be >= 1
        if k == 0:
            for i in range(n):
                if s[i] == 'N':
                    return "NO"

        # For k=0, we need all ? to become Y and no N's at all
        for i in range(n):
            if s[i] == 'N':
                return "NO"

        return "YES"

    return "YES"

