def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "NO\n"

    n, m = map(int, lines[0].split())

    # Build 2-SAT implication graph
    # Node 2*i: x_i = true, Node 2*i+1: x_i = false
    adj = [[] for _ in range(2 * m)]

    for i in range(1, len(lines)):
        if i > n:
            break

        parts = list(map(int, lines[i].split()))
        ki = parts[0]
        literals = parts[1:]

        for j in range(len(literals)):
            literal = literals[j]
            var_idx = abs(literal) - 1

            if literal > 0:
                node_false = 2 * var_idx + 1  # x is false
                node_true = 2 * var_idx
            else:
                node_false = 2 * var_idx
                node_true = 2 * var_idx + 1  # -x is true means x is false

            for k in range(len(literals)):
                if j == k:
                    continue

                other = literals[k]
                other_var_idx = abs(other) - 1

                if other > 0:
                    other_node_true = 2 * other_var_idx
                else:
                    other_node_true = 2 * other_var_idx + 1

                adj[node_false].append(other_node_true)

    # Tarjan's algorithm for SCC
    dfn = [0] * (2 * m)
    low = [0] * (2 * m)
    stack = []
    in_stack = [False] * (2 * m)
    scc = [-1] * (2 * m)
    timer = 0
    scc_cnt = 0

    def tarjan(u):
        nonlocal timer, scc_cnt
        dfn[u] = low[u] = timer
        timer += 1
        stack.append(u)
        in_stack[u] = True

        for v in adj[u]:
            if dfn[v] == 0:
                tarjan(v)
                low[u] = min(low[u], low[v])
            elif in_stack[v]:
                low[u] = min(low[u], dfn[v])

        if low[u] == dfn[u]:
            while stack:
                node = stack.pop()
                in_stack[node] = False
                scc[node] = scc_cnt
                if node == u:
                    break
            scc_cnt += 1

    for i in range(2 * m):
        if dfn[i] == 0:
            tarjan(i)

    # Check satisfiability
    for i in range(m):
        if scc[2 * i] == scc[2 * i + 1]:
            return "NO\n"

    # Assignment: if true node has higher scc than false, set x_i = 1
    assignment = []
    for i in range(m):
        if scc[2 * i] < scc[2 * i + 1]:
            assignment.append("1")
        else:
            assignment.append("0")

    return "YES\n" + "".join(assignment)

