def compute_failure_function(pattern):
    """Compute KMP failure function."""
    m = len(pattern)
    failure = [0] * m
    k = 0
    for q in range(1, m):
        while k > 0 and pattern[k] != pattern[q]:
            k = failure[k-1]
        if pattern[k] == pattern[q]:
            k += 1
        failure[q] = k
    return failure

def get_kmp_automaton(pattern):
    """Build KMP transition table for pattern matching automaton."""
    p_len = len(pattern)
    failure = compute_failure_function(pattern)
    TRANS = [[0] * 26 for _ in range(p_len + 1)]

    for state in range(p_len + 1):
        for char_code in range(26):
            if state == p_len:
                TRANS[state][char_code] = 0
                continue

            char = chr(ord('A') + char_code)
            k = state
            while k > 0 and k < p_len and pattern[k] != char:
                k = failure[k-1]

            if k < p_len and pattern[k] == char:
                TRANS[state][char_code] = k + 1
            else:
                TRANS[state][char_code] = 0

    return TRANS


