    # Build automaton for virus pattern
    TRANS = get_kmp_automaton(virus)

    # DP: dp[i][j][k] = max LCS length using s1[:i], s2[:j] ending in virus state k
    dp = [[[0] * p for _ in range(m + 1)] for _ in range(n + 1)]

    # Parent for reconstruction: (i, j, k) -> (prev_i, prev_j, prev_k, taken_type)
    parent_dict = {}

    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(p):
                char1 = s1[i - 1] if i > 0 else ''
                char2 = s2[j - 1] if j > 0 else ''

                # Option 1: Take both characters (if they match)
                if i > 0 and j > 0 and char1 == char2:
                    new_k = TRANS[k][ord(char1) - ord('A')]
                    if new_k < p:
                        if dp[i][j][new_k] < dp[i - 1][j - 1][k] + 1:
                            dp[i][j][new_k] = dp[i - 1][j - 1][k] + 1
                            parent_dict[(i, j, new_k)] = (i - 1, j - 1, k, 3)

