                        dp[i][j][k] = dp[i - 1][j][k]
                        parent_dict[(i, j, k)] = (i - 1, j, k, 1)

                # Option 3: Skip character from s2  
                if j > 0:
                    if dp[i][j][k] < dp[i][j - 1][k]:
                        dp[i][j][k] = dp[i][j - 1][k]
                        parent_dict[(i, j, k)] = (i, j - 1, k, 0)

    # Find best final state
    best_len = -1
    best_k = -1
    for k in range(p):
