        span = 1 << (j - 1)
        end = n - span + 1
        for i in range(end):
            st_max[j][i] = max(st_max[j-1][i], st_max[j-1][i + span])
            st_min[j][i] = min(st_min[j-1][i], st_min[j-1][i + span])

    def query_max(l, r):
        length = r - l + 1
        span = length.bit_length() - 1
        return max(st_max[span][l], st_max[span][r - (1 << span) + 1])

    def query_min(l, r):
        length = r - l + 1
        span = length.bit_length() - 1
        return min(st_min[span][l], st_min[span][r - (1 << span) + 1])

    potentials = []
    for l in range(n):
