    queue = deque([(start_r, start_c, [])])
    visited = {(start_r, start_c)}

    while queue:
        r, c, path = queue.popleft()

        if r == finish_r and c == finish_c:
            return '\n'.join(path) + '\n'

        # Try each direction
        for move_char in ['R', 'D', 'L', 'U']:
