    def is_valid(subset):
        """Check if this subset makes NONE of the predictions match actual counts"""
        counts = [0] * n
        for person in subset:
            for i in range(n):
                if matrix[person][i] == 1:
                    counts[i] += 1

        for i in range(n):
            if counts[i] != predictions[i]:
                return False
        return True

    from itertools import combinations

    for k in range(n + 1):
        for combo in combinations(range(n), k):
            if is_valid(combo):
                return str(len(combo)) + '\n' + ' '.join(map(str, [c + 1 for c in combo])) + '\n'

    return '-1\n'

