    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    attempts = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        attempts.append((parts[0], int(parts[1])))

    count = 0

    def backtrack(idx, code):
        nonlocal count

        # Early pruning: check constraints
        for i in range(m):
            target = attempts[i][1]
            current_matches = sum(1 for j in range(idx) if code[j] == int(attempts[i][0][j]))
            remaining_positions = n - idx

            needed = target - current_matches
            if needed < 0 or needed > remaining_positions:
                return

        if idx == n:
            valid = True
            for i in range(m):
                actual_matches = sum(1 for j in range(n) if code[j] == int(attempts[i][0][j]))
                if actual_matches != attempts[i][1]:
                    valid = False
                    break
            if valid:
                count += 1
            return

        for bit in [0, 1]:
            code[idx] = bit
            backtrack(idx + 1, code)
            code[idx] = 1 - bit

    backtrack(0, [0] * n)
    return str(count)

