def solution(X_str):
    MOD = 10**9 + 7
    X_digits = [int(c) for c in X_str.strip()]
    n = len(X_digits)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, tight, counts):
        if pos == n:
            if all(c == 0 for c in counts):
                return 0
            val = 0
            for d in range(10):
                for _ in range(counts[d]):
                    val = (val * 10 + d) % MOD
            return val

        result = 0
        upper = X_digits[pos] if tight else 9

        for d in range(0, upper + 1):
            new_tight = tight and (d == upper)
            new_counts = tuple(counts[i] + (1 if i == d else 0) for i in range(10))
            result = (result + dp(pos + 1, new_tight, new_counts)) % MOD

        return result

    return str(dp(0, True, tuple(0 for _ in range(10)))) % MOD

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    # Stack of (sum, count) representing segments
    stack = [(a[0], 1)]

    for i in range(1, n):
        x = a[i]
        while True:
            if not stack:
                break
            total, count = stack[-1]
            current_avg = total / count
            if x >= current_avg:
                # x is greater than or equal to the average, so push it as new segment
                stack.append((x, 1))
                break
            else:
                # x is less than the average, merge it with the previous segment
                stack.pop()
                total += x
                count += 1
                stack.append((total, count))

    result = []
    for total, count in stack:
        for _ in range(count):
            result.append(total / count)

    # Format output: integers without decimal, floats with precision
    output = []
    for val in result:
        if val == int(val):
            output.append(str(int(val)))
        else:
            output.append('{:.10f}'.format(val))

    return '\n'.join(output) + '\n'

