def solution(s):
    n, k, m = map(int, s.split())
    MOD = 10**9 + 7

    if k == 1:
        return str(n)

    # Memoization cache for DP
    memo = {}

    def count_paths(current_pos, visited_tuple, path_len):
        """
        Count valid paths from current_pos
        with tracked visited planets and remaining path length
        """
        # Base case: we've visited k planets
        if path_len == k:
            return 1

        # Create state tuple for memoization
        state = (current_pos, path_len, visited_tuple)
        if state in memo:
            return memo[state]

        total = 0
        # Next planet must satisfy: 1 <= y <= current_pos + m
        bound = min(n, current_pos + m)

        # Try all valid next planets
        for next_pos in range(1, bound + 1):
            if next_pos not in visited_tuple:
                # Recursively count paths from next planet
                new_visited = (next_pos,) + visited_tuple
                total = (total + count_paths(next_pos, new_visited, path_len + 1)) % MOD

        memo[state] = total
        return total

    # Try each starting planet
    total_count = 0
    for start_pos in range(1, n + 1):
        # Start with just the starting planet marked as visited
        total_count = (total_count + count_paths(start_pos, (start_pos,), 1)) % MOD

    return str(total_count)
